def solve_case_2(target_sum=800):
    solutions = []
    primes_up_to_800 = []
    # Generate primes up to 800
    for i in range(2, target_sum + 1):
        if is_prime(i):
            primes_up_to_800.append(i)

    # Iterate over q and r such that q + r = 800 and q < r
    for q in primes_up_to_800:
        r = target_sum - q
        if r <= q or not is_prime(r):
            continue

        # q and r are a valid prime pair summing to 800
        # Iterate over p < q
        for p in primes_up_to_800:
            if p >= q:
                break

            # Check the four primality conditions
            # 1. p+q-r
            cond1 = p + q - r
            if not is_prime(cond1):
                continue

            # 2. q+r-p
            cond2 = target_sum - p
            if not is_prime(cond2):
                continue

            # 3. r+p-q
            cond3 = r + p - q
            if not is_prime(cond3):
                continue

            # 4. p+q+r
            cond4 = p + target_sum
            if not is_prime(cond4):
                continue

            # If all conditions pass, we found a solution
            solutions.append((p, q, r))
    return solutions

solutions = solve_case_2()
